-- Set programs that you use
local terminal    = "ghostty"
local fileManager = "thunar"   -- GUI; yazi (terminal) disponivel via `yazi` no ghostty
local menu        = "rofi -show drun -matching-negate-char '>'"   -- ">" nao filtra a lista (comandos com >; ver rofi/config.rasi)


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
hl.on("hyprland.start", function ()
    -- uwsm: exporta o ambiente p/ o systemd e marca a sessao como pronta
    -- (inofensivo se o Hyprland nao foi iniciado via uwsm).
    hl.exec_cmd("sh -c 'command -v uwsm >/dev/null && uwsm finalize 2>/dev/null || true'")
    -- Login = autologin no tty1 -> .zprofile -> uwsm start hyprland. Como o login
    -- do tty1 e automatico (sem senha), TRAVAMOS a sessao no hyprlock ja no start
    -- via lock.sh (guard RESILIENTE: relanca se o hyprlock morrer sem desbloquear,
    -- p/ o desktop nunca ficar exposto). A sessao nasce na tela de senha a cada boot.
    -- Para abrir direto no desktop (sem travar no boot), comente a linha abaixo.
    hl.exec_cmd("~/.config/hypr/scripts/lock.sh")
    -- Sessao systemd + portais: como o Hyprland e lancado do TTY (sem display
    -- manager), o graphical-session.target nao sobe sozinho. Sem ele, os portais
    -- (xdg-desktop-portal) e o polkit nao iniciam -> apps GTK ficam LENTOS.
    -- tty-graphical-session.target (em ~/.config/systemd/user) ativa o target.
    hl.exec_cmd("sh -c 'dbus-update-activation-environment --systemd --all; systemctl --user start tty-graphical-session.target; systemctl --user start xdg-desktop-portal.service hyprpolkitagent.service'")
    -- Launcher = rofi (SUPER+Espaco). Nativo Wayland, abre instantaneo a frio,
    -- sem daemon (nao precisa de servico residente como o antigo walker/elephant).
    -- Wallpaper: restaura o ULTIMO selecionado por monitor (default so no 1o boot)
    hl.exec_cmd("~/.config/waybar/scripts/wallpaper-restore.sh")
    -- Barra de status: o script lanca uma Waybar POR MONITOR (fixada a sua
    -- saida) e cuida do auto-hide em fullscreen + revelar-ao-hover de forma
    -- independente por monitor. (Por isso NAO chamamos "waybar" direto aqui.)
    -- Roda como SERVICO do systemd (hypr/waybar-fullscreen.service): watchdog externo reinicia o daemon se
    -- ele travar (a barra ficava escondida/vazia). Idempotente: se ja estiver ativo, nao faz nada.
    hl.exec_cmd("systemctl --user start waybar-fullscreen.service")
    -- Atualiza os botoes de workspace (custom/ws*) ao trocar/abrir/fechar janela.
    -- Necessario porque o clique nativo do waybar quebra na config Lua (bug upstream);
    -- usamos botoes custom que chamam hl.dsp.focus, e este daemon os mantem ao vivo.
    hl.exec_cmd("systemctl --user start waybar-ws-watch.service")   -- servico (Restart=always); ver hypr/waybar-ws-watch.service
    -- Notificacoes (daemon + central)
    hl.exec_cmd("swaync")
    -- Gerenciador de inatividade (dim/lock/dpms)
    hl.exec_cmd("hypridle")
    -- Historico de clipboard (cliphist grava texto e imagens copiados)
    hl.exec_cmd("wl-paste --type text  --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
end)

-- Monitor conectado a QUENTE (hotplug): a waybar-por-monitor ja reage sozinha
-- (o waybar-fullscreen.sh escuta o socket de eventos), mas o WALLPAPER nao —
-- sem isto o monitor recem-plugado fica SEM papel de parede (aparencia de
-- "Hyprland cru"). Aqui restauramos o wallpaper quando um monitor e adicionado.
hl.on("monitor.added", function()
    hl.exec_cmd("~/.config/waybar/scripts/wallpaper-restore.sh")
end)


