local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + C", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.fullscreen({ mode = "fullscreen" }))           -- tela cheia (preenche o monitor, na frente)
hl.bind(mainMod .. " + SHIFT + Space", hl.dsp.window.float({ action = "toggle" }))      -- alternar janela flutuante
hl.bind(mainMod .. " + space", hl.dsp.exec_cmd(menu))
-- Picture-in-Picture p/ QUALQUER janela (hypr/scripts/pip.sh): flutuante e pequena, na workspace dela;
-- SUPER+CTRL+O fixa em todas as workspaces. Posicao livre: SUPER + mouse esquerdo arrastando.
local PIP = "~/.config/hypr/scripts/pip.sh"
hl.bind(mainMod .. " + O",         hl.dsp.exec_cmd(PIP .. " toggle"))        -- liga/desliga o PiP da janela ativa
hl.bind(mainMod .. " + CTRL + O",  hl.dsp.exec_cmd(PIP .. " pin"))           -- fixa/solta em todas as workspaces
hl.bind(mainMod .. " + SHIFT + O", hl.dsp.exec_cmd(PIP .. " next"))          -- proximo canto (horario)
hl.bind(mainMod .. " + ALT + left",  hl.dsp.exec_cmd(PIP .. " nudge -40 0"), { repeating = true })  -- ajuste fino
hl.bind(mainMod .. " + ALT + right", hl.dsp.exec_cmd(PIP .. " nudge 40 0"),  { repeating = true })
hl.bind(mainMod .. " + ALT + up",    hl.dsp.exec_cmd(PIP .. " nudge 0 -40"), { repeating = true })
hl.bind(mainMod .. " + ALT + down",  hl.dsp.exec_cmd(PIP .. " nudge 0 40"),  { repeating = true })
hl.bind(mainMod .. " + ALT + equal", hl.dsp.exec_cmd(PIP .. " size +"))      -- aumenta o PiP
hl.bind(mainMod .. " + ALT + minus", hl.dsp.exec_cmd(PIP .. " size -"))      -- diminui o PiP
-- Extensoes do rofi (ver arch/ROFI.md). O rofi-ext.sh resolve os caminhos.
hl.bind(mainMod .. " + equal",     hl.dsp.exec_cmd("~/.config/rofi/scripts/rofi-ext.sh calc"))   -- calculadora
hl.bind(mainMod .. " + T",         hl.dsp.exec_cmd("~/.config/rofi/scripts/rofi-ext.sh trans"))  -- tradutor (EN/PT)
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exec_cmd("~/.config/rofi/scripts/rofi-ext.sh files"))  -- navegar arquivos
hl.bind(mainMod .. " + M",         hl.dsp.exec_cmd("~/.config/rofi/scripts/rofi-ext.sh mixer"))  -- mixer de volume por programa
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Extras (Fase 2)
hl.bind(mainMod .. " + F",         hl.dsp.window.fullscreen({ mode = "fullscreen" })) -- tela cheia
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ mode = "fullscreen" })) -- tela cheia real
hl.bind(mainMod .. " + SHIFT + R", hl.dsp.exec_cmd("hyprctl reload"))                 -- recarregar config
-- Tela PRETA ao acordar da suspensao (maquina viva): religa DPMS, reaplica monitores e reinicia o
-- hyprlock. { locked = true } = vale TAMBEM com a sessao travada (e la que o problema aparece).
-- Script: hypr/scripts/video-reset.sh (log em ~/.cache/resume-log/resume.log).
hl.bind(mainMod .. " + CTRL + ALT + R", hl.dsp.exec_cmd("~/.config/hypr/scripts/video-reset.sh"), { locked = true })
hl.bind(mainMod .. " + L",         hl.dsp.exec_cmd("loginctl lock-session"))          -- bloquear (hyprlock)
hl.bind(mainMod .. " + N",         hl.dsp.exec_cmd("swaync-client -t -sw"))           -- central de notificacoes

-- Extras (Fase 3)  — screenshots no esquema "P" (de Print), sem tecla Print fisica
local S = "~/.config/waybar/scripts"
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.exec_cmd(S .. "/screenshot.sh region"))  -- print de regiao (+satty)
hl.bind(mainMod .. " + CTRL + P",  hl.dsp.exec_cmd(S .. "/screenshot.sh full"))    -- tela cheia
hl.bind(mainMod .. " + ALT + P",   hl.dsp.exec_cmd(S .. "/screenshot.sh window"))  -- janela ativa
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd(S .. "/clipboard.sh"))          -- historico de clipboard
hl.bind(mainMod .. " + W",         hl.dsp.exec_cmd(S .. "/wallpaper.sh"))          -- trocar wallpaper
hl.bind(mainMod .. " + comma",     hl.dsp.exec_cmd(S .. "/settings-menu.sh"))      -- painel de configuracoes

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
-- Waybar em fullscreen: o waybar-fullscreen.sh precisa saber de cliques e Esc para manter a barra aberta enquanto
-- um menu dela (bandeja, slider...) estiver aberto. Binds NAO consumidores: o clique/Esc segue normal para o app.
local WB_TOUCH = 'touch "$XDG_RUNTIME_DIR/waybar/%s" 2>/dev/null'
for _, b in ipairs({ "mouse:272", "mouse:273", "mouse:274" }) do
    hl.bind(b, hl.dsp.exec_cmd(string.format(WB_TOUCH, "click")), { mouse = true, non_consuming = true })
end
hl.bind("Escape", hl.dsp.exec_cmd(string.format(WB_TOUCH, "esc")), { non_consuming = true })
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


